"""Generate public course and portable notebooks from the reviewed curriculum."""
import json
from pathlib import Path
from html import escape as e
ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
BASE='https://sidineyr.github.io/python-swirl-statistics/'
MODULES=json.loads((ROOT/'curriculum/modules.json').read_text())
VIDEOS={v['id']:v for v in json.loads((ROOT/'curriculum/videos.json').read_text())}
CSV=(SITE/'dados/turmas.csv').read_text()
def paragraphs(values): return ''.join('<p>'+e(v)+'</p>' for v in values)
def items(values): return '<ul>'+''.join('<li>'+e(v)+'</li>' for v in values)+'</ul>'
def page(name,title,body,scripts=''):
 schema=json.dumps({'@context':'https://schema.org','@type':'WebPage','name':title,'url':BASE+name,'inLanguage':'pt-BR','author':{'@type':'Person','name':'Sidiney Rodrigues'}},ensure_ascii=False)
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — Python Swirl</title><meta name="description" content="Curso gratuito de Python e estatística: conceitos, vídeos, notebooks e desafios."><link rel="canonical" href="{BASE+name}"><link rel="stylesheet" href="styles.css?rev=3"><script type="application/ld+json">{schema}</script>{scripts}</head><body><a class="skip" href="#conteudo">Saltar para o conteúdo</a><header><nav aria-label="Navegação principal"><a href="index.html">Curso e progresso</a><a href="como-estudar.html">Como estudar</a><a href="recursos.html">Vídeos e fontes</a><a href="instalacao.html">Curso no terminal</a></nav></header><main id="conteudo" tabindex="-1">{body}</main><footer><p>Idealização e direção pedagógica: <a href="https://github.com/sidineyr">professor Sidiney Rodrigues</a>. Curso gratuito e independente, inspirado no <a href="https://swirlstats.com/">swirl do R</a>. Código MIT; conteúdo original CC BY 4.0. Vídeos pertencem aos seus autores.</p><p><a href="privacidade.html">Privacidade</a> · <a href="https://github.com/sidineyr/python-swirl-statistics">Código e documentação</a>. Eventuais lucros serão destinados pelo idealizador ao <a href="https://pequenoprincipe.org.br/doadores/apoie-o-pequeno-principe/">Hospital Pequeno Príncipe</a>; isso não representa parceria nem comprova doações.</p></footer></body></html>'''
def cell(kind,source):
 d={'cell_type':kind,'metadata':{},'source':source.splitlines(keepends=True)}
 if kind=='code': d.update(execution_count=None,outputs=[])
 return d
SETUP='''import math
from statistics import mean, median, pstdev, stdev
from random import Random
import pandas as pd
import matplotlib.pyplot as plt
from io import StringIO
CSV = '''+repr(CSV)+'''
df = pd.read_csv(StringIO(CSV))
# Dados sintéticos: nenhuma linha corresponde a uma pessoa real.
'''
CHECK='''def conferir(valor, esperado, explicacao, tolerancia=0.01):
    """Aceita qualquer procedimento que produza um resultado numérico equivalente."""
    if isinstance(valor, bool) or not isinstance(valor, (int, float)):
        print("Tipo de resposta: informe um número, não texto ou True/False.")
        return False
    if not math.isfinite(valor) or not math.isclose(valor, esperado, abs_tol=tolerancia, rel_tol=1e-9):
        print("Cálculo: resultado diferente do esperado. Revise os dados e o denominador.")
        return False
    print("Resultado conferido. " + explicacao)
    return True
'''
def notebook(m,solved=False):
 setup = SETUP if int(m['slug'][:2]) >= 3 else 'import math\nfrom statistics import mean, median, pstdev, stdev\n'
 cells=[cell('markdown',f'# Python Swirl · {m["title"]}\n\nProfessor Sidiney Rodrigues. Conteúdo original CC BY 4.0.\n\n'+m['problem']+'\n\n## Conceitos\n\n'+'\n\n'.join(m['concepts'])),cell('markdown','## Ambiente\nExecute células de cima para baixo com Shift+Enter. Use Python 3 com pandas e matplotlib. No Colab essas bibliotecas costumam estar disponíveis. Localmente, instale-as se necessário. Não forneça dados pessoais.\n\nUm erro de sintaxe ou execução é mostrado pelo interpretador; a função conferir avalia apenas o resultado numérico, não a autoria ou o método.'),cell('code',setup),cell('code',CHECK),cell('markdown','## Exemplo resolvido\nAntes de executar, preveja a saída.'),cell('code',m['code']),cell('markdown',m['interpretation'])]
 # Keep the worked example for its questions; restore the shared data for challenges only.
 cells += [cell('markdown','## Prática guiada\n'+'\n'.join('- '+v for v in m.get('guided_steps', []))+'\n\nUse os dados do exemplo resolvido nas questões. A tabela comum será restaurada no desafio. Para cada pergunta, escreva sua expressão em uma nova célula e use conferir para revisar o resultado. Aceitam-se soluções equivalentes; não há comparação de strings de código.')]
 for i,q in enumerate(m['questions']):
  cells.append(cell('markdown',f'### Questão {i+1}\n{q["text"]}\n\nPista: {q["hint"]}'))
  cells.append(cell('code',f'# Escreva e execute seu código aqui. Depois confira seu valor:\n# conferir(seu_resultado, {q["expected"]!r}, {q["feedback"]!r})'))
  if solved: cells.append(cell('code', 'resultado = '+q['solution_code']+'\nconferir(resultado, '+repr(q['expected'])+', '+repr(q['feedback'])+')'))
 cells += [cell('markdown','## Desafio com novos dados\n'+m['challenge']+'\n\nDados: CSV sintético com 12 estudantes, 2 notas ausentes, grupos A e B. Nos módulos 1, 2 e 8 use os novos valores descritos no enunciado.\n\n### Critérios\n'+'\n'.join('- '+r for r in m['rubric'])),cell('code',('df = pd.read_csv(StringIO(CSV))\n' if int(m['slug'][:2]) >= 3 else '')+'# Escreva sua análise abaixo.'+(('\n'+m['solution']) if solved else '')),cell('markdown','## Sua interpretação\nSubstitua este texto por sua resposta, com números, unidades, decisões e limites.'),cell('markdown','## Síntese\n'+m['summary']+'\n\nVolte à aula: '+BASE+m['slug']+'.html#questionamentos\n\nSalve uma cópia do notebook ou baixe em Arquivo → Fazer download → .ipynb. O site não importa automaticamente respostas do Colab.')]
 if solved and m.get('solution_text'): cells.append(cell('markdown','## Exemplo de conclusão com limites\n'+m['solution_text']))
 for index, c in enumerate(cells): c['id'] = f'cell-{index:03d}'
 return dict(cells=cells,metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.12'}},nbformat=4,nbformat_minor=5)
for number,m in enumerate(MODULES,1):
 slug=m['slug'];title=m['title']
 for solved in [False,True]:
  name=slug+('-solucao' if solved else '')+'.ipynb'
  (SITE/'notebooks'/name).write_text(json.dumps(notebook(m,solved),ensure_ascii=False,indent=2)+'\n')
 colab='https://colab.research.google.com/github/sidineyr/python-swirl-statistics/blob/main/site/notebooks/'+slug+'.ipynb'
 vid=''
 for vi in [m['video']]+m.get('videos_extra',[]):
  v=VIDEOS[vi]
  vid+=f'<article class="video-card"><h3>{e(v["title"])}</h3><p>{e(v["author"])} · Português · Duração não verificada.</p><button type="button" class="load-video" data-video="{vi}" data-title="{e(v["title"],quote=True)}">Carregar vídeo nesta página</button><div class="video-slot"></div><p><a href="{v["url"]}" target="_blank" rel="noopener">Abrir vídeo no YouTube</a></p></article>'
 qs=''
 for i,q in enumerate(m['questions']):
  qs+=f'<fieldset class="question" data-question="{i}" data-expected="{q["expected"]}" data-tolerance="{q["tolerance"]}"><legend>Questão {i+1}</legend><p>{e(q["text"])}</p><label for="answer-{i}">Resultado numérico (execute Python no notebook)</label><input id="answer-{i}" inputmode="decimal" autocomplete="off"><button type="button" class="check-answer">Conferir resultado</button><p class="answer-feedback" role="status" data-ok="{e(q["feedback"],quote=True)}" data-hint="{e(q["hint"],quote=True)}"></p><details><summary>Preciso de uma pista</summary><p>{e(q["hint"])}</p></details><details><summary>Ver solução comentada</summary><p>{q["expected"]}: {e(q["feedback"])}</p></details></fieldset>'
 criteria=''.join(f'<label class="criterion"><input type="checkbox" data-criterion="{i}"> {e(r)}</label>' for i,r in enumerate(m['rubric']))
 previous=f'<a href="{MODULES[number-2]["slug"]}.html">← Aula anterior</a>' if number>1 else '<a href="index.html">Voltar ao curso</a>'
 nxt=f'<a class="button" href="{MODULES[number]["slug"]}.html">Próxima aula →</a>' if number<10 else '<a class="button" href="index.html">Revisar meu percurso</a>'
 body=f'''<div id="course-lesson" data-module="{slug}"><p class="eyebrow">Módulo {number} de 10 · Cerca de {m['minutes']} minutos, além do tempo de vídeo</p><h1>{e(title)}</h1><p id="lesson-status" role="status"></p><p><strong>Pré-requisitos:</strong> {e(m['prerequisites'])}</p><h2>Ao terminar, você consegue</h2>{items(m['objectives'])}<nav class="lesson-nav" aria-label="Etapas desta aula"><a href="#problema">Problema</a><a href="#conceitos">Conceitos</a><a href="#video">Vídeo</a><a href="#pratica">Prática</a><a href="#questionamentos">Questões</a><a href="#desafio">Desafio</a><a href="#sintese">Síntese</a></nav><section id="problema"><h2>1. Investigue um problema</h2><p>{e(m['problem'])}</p></section><section id="conceitos"><h2>2. Entenda os conceitos</h2>{paragraphs(m['concepts'])}<h3>Exemplo resolvido em Python</h3><pre><code>{e(m['code'])}</code></pre><p>{e(m['interpretation'])}</p><h3>Erros frequentes e limites</h3>{items(m['mistakes'])}</section><section id="video"><h2>3. Acompanhe a aula em vídeo</h2><p>Recurso complementar: o texto e o notebook permitem estudar sem assistir. Os vídeos ensinam o tema; seus dados e ferramentas podem diferir dos exemplos daqui. Títulos e autoria verificados em 8/10/2026; reprodução integral e legendas ainda precisam de revisão.</p>{vid}<a class="button" href="#pratica">Praticar esta aula</a></section><section id="pratica"><h2>4. Execute e investigue</h2><p>O site confere respostas numéricas e guarda reflexões; ele não executa Python. Execute código real no notebook. A conta Google é exigida pelo Colab para executar e salvar; o curso também pode ser feito localmente sem cadastro.</p><p><a class="button" href="{colab}" target="_blank" rel="noopener">Abrir notebook no Colab</a><a href="notebooks/{slug}.ipynb" download>Baixar notebook para Jupyter</a></p>{items(m.get('guided_steps', []))}<ol><li>Leia a pergunta e preveja a saída.</li><li>Execute as células de cima para baixo com Shift+Enter.</li><li>Modifique o exemplo e realize as questões.</li><li>Volte a esta aba e confira seus resultados abaixo.</li></ol><p><a href="como-estudar.html">Ajuda com Colab, Jupyter e mensagens de erro</a> · <a href="dados/turmas.csv" download>Baixar CSV sintético</a></p><label for="prediction">Sua previsão antes de calcular</label><textarea id="prediction" data-note="prediction" rows="3"></textarea><label class="criterion"><input type="checkbox" data-note-check="executed"> Executei código real no notebook e comparei as saídas.</label><a class="button" href="#questionamentos">Responder aos questionamentos</a></section><section id="questionamentos"><h2>5. Confira e interprete</h2><p>A conferência aceita vírgula ou ponto decimal e tolerância de 0,01. Um resultado correto não comprova o método: registre o código no notebook.</p>{qs}<label for="explanation">Explique como calculou e o significado do resultado</label><textarea id="explanation" data-note="explanation" rows="4"></textarea><a class="button" href="#desafio">Aplicar em novos dados</a></section><section id="desafio"><h2>6. Resolva um desafio concreto</h2><p>{e(m['challenge'])}</p><p><strong>Dados:</strong> exemplos e CSV sintéticos, criados para ensinar; não representam estudantes reais. A entrega inclui código executado e interpretação no notebook.</p><details><summary>Pista 1: por onde começar</summary><p>{e(m['hints'][0])}</p></details><details><summary>Pista 2: procedimento</summary><p>{e(m['hints'][1])}</p></details><details><summary>Solução de referência e interpretação</summary><pre><code>{e(m['solution'])}</code></pre>{items(m['rubric'])}{paragraphs([m['solution_text']]) if m.get('solution_text') else ''}<p><a href="notebooks/{slug}-solucao.ipynb" download>Baixar notebook com solução executável</a></p></details><label for="reflection">Sua conclusão, decisões e limitações</label><textarea id="reflection" data-note="reflection" rows="6"></textarea><h3>Revise sua entrega com os critérios</h3><p>Marque somente o que conferiu na sua análise. A avaliação de interpretação é sua; o site não dá nota automática.</p>{criteria}<button type="button" id="complete-lesson">Registrar atividade concluída</button><p id="completion-feedback" role="status"></p></section><section id="sintese"><h2>7. O que você consegue fazer agora?</h2><p>{e(m['summary'])}</p><button type="button" id="redo-lesson">Refazer conferências e autoavaliação</button><p>Refazer mantém seus textos. Use exportação para guardar uma cópia.</p><nav aria-label="Aulas">{previous} {nxt}</nav></section></div>'''
 (SITE/(slug+'.html')).write_text(page(slug+'.html',title,body,'<script defer src="course.js?rev=3"></script>'))
cards=''.join(f'<section data-card="{m["slug"]}"><p>Módulo {i+1} · {m["minutes"]} min + vídeo</p><h3><a href="{m["slug"]}.html">{e(m["title"])}</a></h3><p>{e(m["objectives"][0])}</p><p class="module-state">Ainda não visitado</p></section>' for i,m in enumerate(MODULES))
body=f'''<p class="eyebrow">Curso aberto · Python, estatística e análise de dados</p><h1>Entenda os dados.<br>Execute Python.<br>Explique o resultado.</h1><p>Um curso gratuito idealizado pelo professor Sidiney Rodrigues. Dez módulos ligam conceitos, aulas em vídeo, prática guiada e desafios com novos dados.</p><p>Para iniciantes em programação e estatística. Você precisa de operações aritméticas básicas e acesso a um computador para os notebooks. Cerca de 12 horas de leitura e prática, além dos vídeos; seu ritmo pode variar.</p><a class="button" id="resume-course" href="01-primeiros-passos.html">Começar o curso</a><a href="como-estudar.html">Entender como funciona</a><h2>Seu percurso</h2><p id="course-progress" role="status">Seu progresso fica neste navegador.</p><p>Visitar uma aula e concluir suas atividades são registros separados. Conclusão inclui conferência numérica e autoavaliação; não certifica domínio.</p><button id="export-course" type="button">Exportar respostas e progresso</button><label for="import-course">Restaurar uma exportação deste curso</label><input id="import-course" type="file" accept="application/json,.json"><p id="storage-status" role="status"></p><h2 id="atividades">Escolha uma aula</h2><div class="cards">{cards}</div><h2>O que você entrega</h2><p>Ao final, um notebook com pergunta, dados, limpeza, medidas, gráficos e uma conclusão com limitações. Use dados sintéticos sem dados pessoais. Não há cadastro obrigatório no curso, API paga ou certificado.</p><h2>Atividades da primeira versão</h2><p>As prévias conceituais e o curso local continuam disponíveis. Seus arquivos de progresso da CLI permanecem compatíveis.</p><p><a href="media-mediana.html">Média e mediana</a> · <a href="dispersao.html">Dispersão</a> · <a href="amostragem.html">Amostragem</a> · <a href="instalacao.html">Curso no terminal</a></p>'''
(SITE/'index.html').write_text(page('index.html','Python e estatística com conceitos, vídeos e desafios',body,'<script defer src="course.js?rev=3"></script>'))
helpbody='''<h1>Como estudar e executar Python</h1><p>Em cada aula: problema → conceitos → vídeo → prática → questões → desafio → síntese. O vídeo é opcional; a prática de código é parte da entrega.</p><h2>Com Google Colab</h2><ol><li>Abra o notebook pelo botão da aula. O endereço aponta para um arquivo deste repositório.</li><li>Entre na sua conta Google se o Colab solicitar. Para guardar trabalho, use Arquivo → Salvar uma cópia no Drive. O curso não recebe suas credenciais.</li><li>Conecte ao ambiente de execução e execute as células em ordem, com Shift+Enter. Se pandas ou matplotlib não estiverem disponíveis, instale-os em uma célula com %pip install pandas matplotlib.</li><li>Edite as células de prática e escreva a interpretação. Baixe seu .ipynb para guardar uma cópia.</li><li>Volte à aba do Python Swirl, confira resultados e use a rubrica. Não há sincronização automática entre Colab e site.</li></ol><h2>Sem conta: Jupyter no computador</h2><p>Instale Python 3.10 ou superior. No terminal, execute:</p><pre><code>python -m pip install jupyterlab pandas matplotlib\npython -m jupyterlab</code></pre><p>No Windows, se python não for encontrado, substitua por py -3. Baixe o notebook na aula e abra-o no JupyterLab. O CSV já está incorporado ao notebook para não depender de download externo durante o estudo. Bibliotecas e instalação inicial exigem internet; depois os notebooks podem executar localmente.</p><h2>Quando aparecer um erro</h2><ul><li>SyntaxError: confira parênteses, aspas, dois-pontos e indentação.</li><li>NameError: execute a célula que define o nome e confira a grafia.</li><li>ModuleNotFoundError: instale a biblioteca no mesmo ambiente do notebook.</li><li>Resultado diferente: revise dados, filtro, ausências e denominador. Use pistas graduais.</li></ul><h2>Salvar e retomar</h2><p>O site salva textos, conferências e rubricas neste navegador. Se o armazenamento estiver bloqueado, avisará que a sessão não ficará salva. Exporte respostas na página inicial antes de trocar de dispositivo ou limpar o navegador. Importar uma exportação une os registros; conflitos da mesma aula preservam ambos os textos e pedem nova autoavaliação.</p><h2>Limites da avaliação</h2><p>O site confere números, não executa código nem interpreta automaticamente textos. O notebook executa Python real. A rubrica orienta autoavaliação. Não há evidência de eficácia educacional por piloto com estudantes.</p>'''
(SITE/'como-estudar.html').write_text(page('como-estudar.html','Como estudar',helpbody))
rows=''.join(f'<tr><td>{e(m["title"])}</td><td>{e(VIDEOS[m["video"]]["title"])}</td><td>{e(VIDEOS[m["video"]]["author"])}</td><td><a href="{VIDEOS[m["video"]]["url"]}">YouTube</a></td><td>{e(", ".join(m["objectives"]))}</td></tr>' for m in MODULES)
resources=f'''<h1>Vídeos, fontes e dados</h1><p>Recursos gratuitos em português, com títulos e autoria confirmados por metadados oEmbed do YouTube em 8/10/2026 e correspondência temática conferida nas descrições disponíveis. Duração, legendas e reprodução integral não verificadas; nenhum trecho temporal foi inventado. A duração estimada das aulas não inclui os vídeos.</p><div class="table-scroll"><table><caption>Curadoria de recursos complementares</caption><thead><tr><th>Módulo</th><th>Vídeo</th><th>Autor/canal</th><th>Origem</th><th>Conceitos trabalhados no módulo</th></tr></thead><tbody>{rows}</tbody></table></div><p>No módulo 7 há também <a href="{VIDEOS['3-Qc8ZTrFXI']['url']}">{e(VIDEOS['3-Qc8ZTrFXI']['title'])}</a>, do professor Douglas Maioli. Os vídeos podem cobrir apenas parte dos objetivos; o texto e o notebook complementam o percurso.</p><h2>Fontes técnicas primárias</h2><ul><li><a href="https://docs.python.org/3/tutorial/introduction.html">Tutorial oficial de Python: operações, tipos e listas</a></li><li><a href="https://pandas.pydata.org/docs/getting_started/intro_tutorials/index.html">Tutoriais oficiais do pandas: tabelas, leitura, seleção e gráficos</a></li><li><a href="https://docs.python.org/3/library/statistics.html">Biblioteca statistics: média, mediana e desvios padrão</a></li><li><a href="https://www.itl.nist.gov/div898/handbook/">NIST: estatística e exploração de dados</a></li></ul><h2>Dados e licença</h2><p>O <a href="dados/turmas.csv">CSV de turmas</a> contém 12 registros inventados para ensinar. Não são dados de pesquisa nem pessoas reais. ID é identificador nominal; turma é categoria A/B; horas é duração de estudo em horas; nota é uma pontuação sintética de 0 a 10. Duas notas estão ausentes. Conteúdo e dados originais: CC BY 4.0. Vídeos seguem as condições de seus autores e da plataforma; não foram copiados ou redistribuídos.</p>'''
(SITE/'recursos.html').write_text(page('recursos.html','Vídeos, fontes e dados',resources))
# Keep old pages indexed and update the sitemap to cover every generated page.
urls=[BASE+p.name for p in sorted(SITE.glob('*.html'))]
(SITE/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>'+u+'</loc></url>\n' for u in urls)+'</urlset>\n')
print('Generated 10 modules, 20 notebooks, home, help and resources.')
